    {id:"collaborator",title:"Agent Collaborator",xpMin:280,description:"Can define completion criteria, check evidence, and stop promptly when something goes wrong."},
    {id:"designer",title:"Workflow Designer",xpMin:500,description:"Can break a task into steps that can be approved, verified, and rolled back."},
    {id:"engineer",title:"Agent Systems Practitioner",xpMin:760,description:"Can design tool boundaries, stopping conditions, observability, and evaluations."}
